                public static void SeedProductCrops(this ModelBuilder modelBuilder)
        {
            var productCrops = new System.Collections.Generic.List<ProductCrop>();
            var rnd = new System.Random(42);
            var cropInstructions = new System.Collections.Generic.Dictionary<int, string>
            {
                { 1, "Phòng trừ sâu bệnh, giúp cứng cây, đứng lá, tăng năng suất lúa." },
                { 2, "Bổ sung dinh dưỡng và bảo vệ nấm bệnh cho cây ăn trái." },
                { 3, "An toàn cho rau màu, phòng trừ sâu tơ, sâu xanh." },
                { 4, "Kiểm soát rệp sáp, nấm hồng trên cây công nghiệp." },
                { 5, "Trừ tuyến trùng, bảo vệ củ, giúp củ to, đều." },
                { 6, "Giữ hoa bền màu, phòng bệnh đốm lá." },
                { 7, "Phòng trừ rỉ sắt, rệp sáp hại cà phê." },
                { 8, "Kiểm soát nứt thân xì mủ, rầy phấn trắng trên sầu riêng." },
                { 9, "Bảo vệ rễ hồ tiêu, ngừa bệnh chết nhanh chết chậm." },
                { 10, "Bảo vệ hoa và trái non xoài khỏi thán thư." },
                { 11, "Kiểm soát sâu bệnh trên bắp cải hiệu quả." },
                { 12, "Trừ nhện đỏ, rầy chổng cánh bảo vệ cam bưởi." },
                { 13, "Ngừa sâu keo mùa thu, bệnh khô vằn trên ngô." }
            };

            for (int i = 1; i <= 83; i++)
            {
                // Each product is suitable for 1 to 3 random crops
                int numCrops = rnd.Next(1, 4);
                var selectedCrops = new System.Collections.Generic.HashSet<int>();
                while (selectedCrops.Count < numCrops)
                {
                    selectedCrops.Add(rnd.Next(1, 14));
                }

                foreach (var cropId in selectedCrops)
                {
                    productCrops.Add(new ProductCrop 
                    { 
                        ProductId = i, 
                        CropId = cropId, 
                        UsageInstruction = cropInstructions[cropId] 
                    });
                }
            }
            modelBuilder.Entity<ProductCrop>().HasData(productCrops);
        }
    }
